/**
 * Interface language. English strings are the keys: t('Rest') looks up the Russian dictionary and
 * falls back to English. Text generated by the backend (events, news, errors) goes through tx(),
 * which matches templates. Player names, map titles and chat are never translated.
 */
import { STAT_LABELS } from './i18n.keys'
import { RU, RU_PATTERNS } from './i18n.ru'

export type Lang = 'ru' | 'en'
const KEY = 'tycoon.lang'

function initial(): Lang {
  try {
    return localStorage.getItem(KEY) === 'en' ? 'en' : 'ru'
  } catch {
    return 'ru'
  }
}

let current: Lang = initial()

export const getLang = (): Lang => current

/** Switches the language. Reloads the page so every component re-renders in the new language. */
export function setLang(lang: Lang, reload = true) {
  localStorage.setItem(KEY, lang)
  current = lang
  if (reload) window.location.reload()
}

function fill(s: string, vars?: Record<string, string | number>) {
  return vars ? s.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m)) : s
}

/** Translate an interface string; {name} placeholders are filled from vars. */
export function t(en: string, vars?: Record<string, string | number>): string {
  return fill(current === 'ru' ? (RU[en] ?? en) : en, vars)
}

/** Translate free text produced by the backend: exact match first, then templates. */
export function tx(text: string | null | undefined): string {
  if (!text || current !== 'ru') return text ?? ''
  if (RU[text]) return RU[text]
  for (const [re, out] of RU_PATTERNS) {
    const m = text.match(re)
    if (m) return typeof out === 'function' ? out(...m.slice(1)) : out.replace(/\$(\d)/g, (_, i: string) => m[Number(i)] ?? '')
  }
  return text
}

/** Russian plural form: plural(5, 'день', 'дня', 'дней') -> 'дней'. */
export function plural(n: number, one: string, few: string, many: string): string {
  if (current !== 'ru') return n === 1 ? one : few
  const a = Math.abs(n) % 100
  const b = a % 10
  if (a > 10 && a < 20) return many
  if (b === 1) return one
  if (b >= 2 && b <= 4) return few
  return many
}

/** "5 days" / "5 дней". */
export function days(n: number): string {
  return current === 'ru' ? `${n} ${plural(n, 'день', 'дня', 'дней')}` : `${n} day${n === 1 ? '' : 's'}`
}

/** Locale for Intl (weekday names, dates). */
export const locale = (): string => (current === 'ru' ? 'ru-RU' : 'en-US')

/** Label for an attribute key such as "snap_aim" (used where the backend sends only keys). */
export function statLabel(key: string): string {
  return t(STAT_LABELS[key] ?? key)
}
